function scenarioCopy(id, tab) {
  const universal = {
    overall: {
      strengths: [
        ['Вы быстро считываете настроение', 'Не нужно долго объяснять, почему сейчас хочется движения, тишины или поддержки — другой обычно ловит смену ритма.'],
        ['Инициатива не повисает в воздухе', 'Когда один предлагает идею, второй скорее развивает её, чем сразу ищет причины отказаться.']
      ],
      frictions: [
        ['Спор может разгоняться слишком быстро', 'Оба реагируете на тон. Через пять минут обсуждение посуды или маршрута может звучать как спор о всей связи.'],
        ['Поддержка иногда выглядит как совет', 'Один хочет, чтобы его сначала просто услышали, а второй уже предлагает решение и невольно обесценивает чувство.']
      ],
      repairs: [
        ['Сначала назвать режим разговора', 'Одна фраза «мне сейчас нужно выговориться, не решать» сильно снижает количество лишних конфликтов.'],
        ['Разделять факт и интерпретацию', 'Сначала: что произошло. Потом: что каждый почувствовал. И только после — что делать дальше.']
      ]
    },
    love: {
      strengths: [
        ['Притяжение чувствуется без усилий', 'Вы замечаете интерес друг друга и хорошо отвечаете на инициативу — связь не приходится всё время “оживлять”.'],
        ['Легко быть яркими рядом', 'Партнёр не просит тебя уменьшиться, а скорее подталкивает проявляться свободнее и смелее.']
      ],
      frictions: [
        ['Пауза может восприниматься как охлаждение', 'Когда одному нужно переварить эмоции, второй может начать добиваться подтверждения чувств прямо сейчас.'],
        ['Шутка иногда попадает в уязвимое место', 'Лёгкий стиль общения хорош, пока один из вас не пытается шуткой закрыть серьёзную тему.']
      ],
      repairs: [
        ['Давать паузе точное время', 'Не исчезать, а сказать: «мне нужен час, в девять вернёмся к разговору». Тогда дистанция не звучит как отказ.'],
        ['Чаще проговаривать очевидное', 'Даже если интерес виден по действиям, короткие прямые слова делают эту связь заметно устойчивее.']
      ]
    },
    home: {
      strengths: [
        ['Можно жить рядом, не слипаясь', 'У каждого остаётся свой ритм, и это не обязательно воспринимается как отсутствие близости.'],
        ['Дом быстро становится живым', 'Вы легко придумываете, как улучшить пространство, пригласить людей или устроить маленькое событие.']
      ],
      frictions: [
        ['Разный порог бытового хаоса', 'Один замечает незакрытые дела раньше и чувствует, что несёт больше, второй ещё не считает ситуацию проблемой.'],
        ['Просьба звучит как контроль', 'Чем дольше молчать, тем резче потом звучит простая просьба — и разговор уходит не туда.']
      ],
      repairs: [
        ['Делить не дела, а зоны ответственности', 'Не «помогать с кухней», а полностью владеть своей зоной — от замечания проблемы до результата.'],
        ['Согласовать минимальный стандарт', 'Что обязательно делаем ежедневно, что раз в неделю, а что каждый организует по своему вкусу.']
      ]
    },
    work: {
      strengths: [
        ['Вы усиливаете разные части процесса', 'Один лучше видит направление и людей, второй быстрее превращает это в последовательность шагов.'],
        ['Высокий темп не пугает', 'Вместе легче пройти стартовую неопределённость и не потерять азарт после первых сложностей.']
      ],
      frictions: [
        ['Оба можете считать решение своим', 'Идеи быстро смешиваются, и в момент результата становится неясно, кто отвечает и чьё слово последнее.'],
        ['Обратная связь звучит личнее, чем хотелось', 'Когда нет отдельного рабочего формата, замечание по задаче легко воспринимается как оценка человека.']
      ],
      repairs: [
        ['Назначать владельца каждого решения', 'Обсуждать можно вместе, но у конкретного вопроса всегда должен быть один человек с финальным словом.'],
        ['Развести рабочий и личный разговор', 'Сначала коротко закрыть задачу, потом отдельно обсудить эмоции — не смешивать оба слоя в одном сообщении.']
      ]
    },
    travel: {
      strengths: [
        ['Вместе легче решиться на новое', 'Незнакомое место, странный маршрут или внезапный план скорее вызывают любопытство, чем тревогу.'],
        ['Вы хорошо создаёте впечатления', 'Один замечает варианты, другой быстро выбирает — поэтому поездка не превращается в бесконечный поиск идеального решения.']
      ],
      frictions: [
        ['Можно перегрузить маршрут', 'Когда обоим интересно всё, отдых превращается в ещё один проект с дедлайнами и усталостью.'],
        ['Усталость проявляется по-разному', 'Один становится молчаливее, другой — активнее и разговорчивее, из-за чего легко неверно прочитать состояние партнёра.']
      ],
      repairs: [
        ['Оставлять одно пустое окно в день', 'Не “если успеем”, а заранее незапланированные два-три часа, где можно поменять решение без чувства провала.'],
        ['Заранее договориться о сигналах усталости', 'Простая фраза или шкала от 1 до 10 помогает не принимать перегрузку другого на свой счёт.']
      ]
    }
  };

  const data = JSON.parse(JSON.stringify(universal[tab]));
  if (id === 'roman' && tab === 'home') data.frictions[0] = ['Свобода сталкивается с потребностью в опоре', 'Роман легче меняет договорённость по ходу, а тебе важно понимать, что правило действительно действует.'];
  if (id === 'irina' && tab === 'work') data.strengths[0] = ['Ты видишь смысл, Ирина удерживает систему', 'Это редкая связка, где идея не теряется в процессе, а процесс не начинает жить ради самого себя.'];
  if (id === 'anna' && tab === 'overall') data.repairs[0] = ['Не ждать, что другая догадается', 'В этой связи конфликт чаще рождается не из грубости, а из слишком долгого и аккуратного молчания.'];
  return data;
}
